//! Control flow monad transformers for do-notation (#1818 Phase 4A).
//!
//! Kernel axioms required by the ControlStack:
//! - `Except` type: `Except.ok`, `Except.error`
//! - `ExceptT` transformer: `ExceptT`, `ExceptT.mk`, `ExceptT.run`
//! - `OptionT` transformer: `OptionT`, `OptionT.mk`, `OptionT.run`, `OptionT.fail`
//! - `MonadExcept`: `throw`, `tryCatch`, `tryCatchThe`, `tryFinally`
//!
//! Reference: ~/lean4-ref/src/Init/Control/Except.lean
//! Reference: ~/lean4-ref/src/Init/Control/Option.lean

use super::decl_builder::EnvDeclBuilder;
use crate::env::monad_term::{cst, lparam, type_at, Tele};
use crate::env::{Constructor, Declaration, EnvError, Environment, InductiveDecl, InductiveType};
use crate::expr::{BinderInfo, Expr, ExprKind};
use crate::level::Level;
use crate::name::Name;

impl Environment {
    /// Initialize Except type, ExceptT, OptionT, and MonadExcept.
    pub fn init_except_t(&mut self) -> Result<(), EnvError> {
        if self.except_t_init {
            return Ok(());
        }
        self.init_except_type()?;
        self.init_except_bind()?;
        // `ExceptT` is Lean's DEFINITION `m (Except ε α)` with its `[Monad m]`
        // operations, `Except` and `ExceptT` get their `Monad` instances, and
        // `MonadExcept` is Lean's class (`data_monad_transformers.rs`). Until
        // 2026-09-28 `ExceptT` was an opaque axiom and `MonadExcept.throw` an
        // instance-less axiom `ε → m α`, which proved `False` at `m := fun _
        // => Empty` (`docs/issues/2026-09-28-prelude-pure-proves-false.md`).
        self.init_except_t_defs()?;
        self.init_except_monad_instance()?;
        self.init_monad_except_class()?;
        self.except_t_init = true;
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn has_except_t(&self) -> bool {
        self.except_t_init
    }

    /// Initialize OptionT transformer (used by BreakT/ContinueT).
    pub fn init_option_t(&mut self) -> Result<(), EnvError> {
        if self.option_t_init {
            return Ok(());
        }
        // Lean's `OptionT m α := m (Option α)` with `[Monad m]` operations
        // and `OptionT.instMonad` (`data_monad_transformers.rs`). The opaque
        // `OptionT` / `OptionT.run` / `OptionT.fail` axioms this replaced
        // proved `False` TOGETHER: `OptionT.run (OptionT.fail)` was an
        // `m (Option α)` for any `m`.
        //
        // IMPORT MODE (`suppress_lossy_structure_stubs`): nothing is
        // registered — the operations need the `Monad` class, which the import
        // prelude withholds so the genuine `.olean` hierarchy (and Lean's own
        // `OptionT`) imports through the checked path.
        if !self.suppress_lossy_structure_stubs {
            self.init_option()?;
            self.init_option_t_defs()?;
        }
        self.option_t_init = true;
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn has_option_t(&self) -> bool {
        self.option_t_init
    }

    /// `inductive Except (ε : Type u) (α : Type v) : Type (max u v)` with
    /// `error` / `ok`, Lean 4.8.0's two-universe declaration
    /// (`Init/Prelude.lean`; `#print Except` on the pinned toolchain:
    /// `Except.{u, v} : Type u → Type v → Type (max u v)`), as a genuine
    /// 2-constructor inductive with a real `Except.rec` / `Except.casesOn`
    /// generated by `add_inductive`.
    ///
    /// Until 2026-10-16 this was a SINGLE-universe stand-in (`Type u → Type u
    /// → Type u`), which shadowed the imported `Except.{u, v}` whenever a
    /// source file imported an `.olean` on top of the builtin prelude
    /// (`import Lean.Data.Json`: "expected Except String Lean.Json, got
    /// Except String Lean.Json", trust-ir gap G32, ledger class (102)) and
    /// refused `Except String Type`. Every dependent (`Except.bind`,
    /// `ExceptT`, `Except.instMonad`, the `MonadExcept` instances) now spells
    /// Lean's universe telescope.
    ///
    /// Constructor order is Lean 4's canonical `error`, then `ok`, so the
    /// generated `Except.casesOn.{w, u, v}` takes the error handler as its
    /// first minor premise and the ok handler as its second — matching the
    /// `Except.casesOn scrut err_handler ok_handler` shape that the
    /// monad-presentation tactic (`monad_pres.rs`) expects. Axiom-free.
    fn init_except_type(&mut self) -> Result<(), EnvError> {
        let (u, v) = (lparam("u"), lparam("v"));
        let uv = [u.clone(), v.clone()];
        // `Type (max u v)`, spelled as Lean's `.olean` stores it:
        // `Sort (max (u + 1) (v + 1))`, so an imported `Except` meets an
        // equal type, not only an equivalent one.
        let except_type = Expr::pi(
            BinderInfo::Default,
            type_at(&u),
            Expr::pi(
                BinderInfo::Default,
                type_at(&v),
                Expr::sort(Level::max(Level::succ(u.clone()), Level::succ(v.clone()))),
            ),
        );
        // Except.error : {ε : Type u} → {α : Type v} → ε → Except ε α
        // Except.ok    : {ε : Type u} → {α : Type v} → α → Except ε α
        let ctor_type = |is_ok: bool| {
            let mut t = Tele::new();
            let e = t.imp(type_at(&u));
            let a = t.imp(type_at(&v));
            let _ = t.arg(if is_ok { a.clone() } else { e.clone() });
            t.pi(Expr::apps(cst("Except", &uv), [e, a]))
        };
        self.add_inductive(InductiveDecl {
            level_params: vec![Name::from_string("u"), Name::from_string("v")],
            num_params: 2,
            types: vec![InductiveType {
                name: Name::from_string("Except"),
                type_: except_type,
                constructors: vec![
                    Constructor {
                        name: Name::from_string("Except.error"),
                        type_: ctor_type(false),
                    },
                    Constructor {
                        name: Name::from_string("Except.ok"),
                        type_: ctor_type(true),
                    },
                ],
            }],
        })
    }

    /// `protected def Except.bind.{u, u_1, u_2} {ε : Type u} {α : Type u_1}
    /// {β : Type u_2} (ma : Except ε α) (f : α → Except ε β) : Except ε β`,
    /// Lean 4.8.0's universe telescope (`#print Except.bind`), as a genuine,
    /// axiom-free `Definition` whose body is the canonical `Except.casesOn`
    /// split. (Lean's body goes through the matcher `Except.map.match_1`,
    /// which unfolds to the same `casesOn`.)
    ///
    /// The body
    ///   `fun ε α β e f =>
    ///      Except.casesOn.{max u u_2 + 1, u, u_1} ε α (fun _ => Except ε β) e
    ///        (fun err => Except.error ε β err) (fun a => f a)`
    /// reduces definitionally: `Except.bind (.ok a) f ⟶ f a` and
    /// `Except.bind (.error e) f ⟶ .error e`. That is exactly what
    /// `Sem.run_bind := rfl` (`(Sem.run m s).bind …`) needs to close, and it
    /// is what `Bind.bind` on the `Except` monad unfolds to, so registering it
    /// keeps the dot-notation `e.bind f` sound. `add_decl` kernel-checks the
    /// definition; no axioms are emitted.
    fn init_except_bind(&mut self) -> Result<(), EnvError> {
        let (u, u1, u2) = (lparam("u"), lparam("u_1"), lparam("u_2"));
        let except = |a_lvl: &Level, e: &Expr, a: &Expr| {
            Expr::apps(
                cst("Except", &[u.clone(), a_lvl.clone()]),
                [e.clone(), a.clone()],
            )
        };
        self.add_tele_def("Except.bind", &["u", "u_1", "u_2"], false, |t| {
            let e = t.imp(type_at(&u));
            let a = t.imp(type_at(&u1));
            let b = t.imp(type_at(&u2));
            let ma = t.arg(except(&u1, &e, &a));
            let f = t.arg(Expr::arrow(a.clone(), except(&u2, &e, &b)));
            let res = except(&u2, &e, &b);
            let motive = {
                let mut t2 = Tele::child(t);
                let _ = t2.arg(except(&u1, &e, &a));
                t2.lam(res.clone())
            };
            let on_error = {
                let mut t2 = Tele::child(t);
                let err = t2.arg(e.clone());
                t2.lam(Expr::apps(
                    cst("Except.error", &[u.clone(), u2.clone()]),
                    [e.clone(), b.clone(), err],
                ))
            };
            let on_ok = {
                let mut t2 = Tele::child(t);
                let x = t2.arg(a.clone());
                t2.lam(Expr::app(f, x))
            };
            // `Except.casesOn.{w, u, u_1}`: the motive universe `w` first
            // (`Except ε β : Type (max u u_2)`), then the inductive's own.
            let motive_lvl = Level::succ(Level::max(u.clone(), u2.clone()));
            let val = Expr::apps(
                cst("Except.casesOn", &[motive_lvl, u.clone(), u1.clone()]),
                [e.clone(), a.clone(), motive, ma, on_error, on_ok],
            );
            (res, val)
        })
    }
    /// `tryCatchThe` and `tryFinally`, still value-less axioms — and
    /// SATISFIABLE ones, unlike the `MonadExcept.throw` axiom that used to sit
    /// here: each returns an inhabitant of a type one of its own arguments
    /// already inhabits (`m α`), so it holds in every model (take the first
    /// argument). The prelude axiom census witnesses that
    /// (`axiom_inhabitation.rs`, `Witness::Hypothesis`).
    ///
    /// # Errors
    /// Propagates checked prerequisite and signature registration errors.
    pub fn init_control_stub_theory(&mut self) -> Result<(), EnvError> {
        if self.suppresses_lossy_structure_stubs() {
            return Ok(());
        }
        self.init_except_t()?;
        let u = Name::from_string("u");
        let v = Name::from_string("v");
        let type_u = Expr::from_kind(ExprKind::Sort(Level::succ(Level::param(u.clone()))));
        let type_v = Expr::from_kind(ExprKind::Sort(Level::succ(Level::param(v.clone()))));

        // tryCatchThe : same signature (typed catch, instance implicit)
        let m_vv = Expr::pi(BinderInfo::Default, type_v.clone(), type_v.clone());
        let tct_type = self.build_try_catch_type(&type_u, &type_v, &m_vv)?;
        if self.get_const(&Name::from_string("tryCatchThe")).is_none() {
            self.add_decl(Declaration::Axiom {
                name: Name::from_string("tryCatchThe"),
                level_params: vec![u.clone(), v.clone()],
                type_: tct_type,
            })?;
        }
        if self.get_const(&Name::from_string("tryFinally")).is_some() {
            return Ok(());
        }

        // tryFinally : {m} → {α β} → m α → m β → m α
        let m_uv = Expr::pi(BinderInfo::Default, type_u.clone(), type_v.clone());
        let tf_type = {
            let mut b = EnvDeclBuilder::new();
            let (m_id, m) = b.fresh_local(m_uv.clone());
            let (alpha_id, alpha) = b.fresh_local(type_u.clone());
            let (beta_id, beta) = b.fresh_local(type_u.clone());
            let m_a = Expr::app(m.clone(), alpha.clone());
            let m_b = Expr::app(m, beta);
            let (body_id, _) = b.fresh_local(m_a.clone());
            let (fin_id, _) = b.fresh_local(m_b.clone());
            let r = m_a.clone();
            let r = b.mk_pi(fin_id, BinderInfo::Default, m_b, r);
            let r = b.mk_pi(body_id, BinderInfo::Default, m_a, r);
            let r = b.mk_pi(beta_id, BinderInfo::Implicit, type_u.clone(), r);
            let r = b.mk_pi(alpha_id, BinderInfo::Implicit, type_u, r);
            let r = b.mk_pi(m_id, BinderInfo::Implicit, m_uv, r);
            b.finish(r)
        };
        self.add_decl(Declaration::Axiom {
            name: Name::from_string("tryFinally"),
            level_params: vec![u, v],
            type_: tf_type,
        })
    }

    /// Build the shared tryCatch type: {ε} → {m} → {α} → m α → (ε → m α) → m α
    fn build_try_catch_type(
        &self,
        type_u: &Expr,
        type_v: &Expr,
        m_ty: &Expr,
    ) -> Result<Expr, EnvError> {
        let mut b = EnvDeclBuilder::new();
        let (eps_id, eps) = b.fresh_local(type_u.clone());
        let (m_id, m) = b.fresh_local(m_ty.clone());
        let (alpha_id, alpha) = b.fresh_local(type_v.clone());
        let m_alpha = Expr::app(m, alpha);
        let (body_id, _) = b.fresh_local(m_alpha.clone());
        let handler_ty = {
            let mut c = EnvDeclBuilder::child_of(&b);
            let (e_id, _) = c.fresh_local(eps.clone());
            let r = m_alpha.clone();
            let r = c.mk_pi(e_id, BinderInfo::Default, eps.clone(), r);
            c.finish_child(r)
        };
        let (h_id, _) = b.fresh_local(handler_ty.clone());
        let r = m_alpha.clone();
        let r = b.mk_pi(h_id, BinderInfo::Default, handler_ty, r);
        let r = b.mk_pi(body_id, BinderInfo::Default, m_alpha, r);
        let r = b.mk_pi(alpha_id, BinderInfo::Implicit, type_v.clone(), r);
        let r = b.mk_pi(m_id, BinderInfo::Implicit, m_ty.clone(), r);
        let r = b.mk_pi(eps_id, BinderInfo::Implicit, type_u.clone(), r);
        Ok(b.finish(r))
    }
}

#[cfg(test)]
mod tests {
    use crate::env::Environment;
    use crate::expr::Expr;
    use crate::name::Name;

    #[test]
    fn test_init_except_t() {
        let mut env = Environment::new();
        env.init_except_t().expect("init_except_t");
        assert!(env.has_except_t());
        assert!(env.get_const(&Name::from_string("tryCatchThe")).is_none());
        assert!(env.get_const(&Name::from_string("tryFinally")).is_none());
        env.init_control_stub_theory()
            .expect("explicit control stub theory");
        env.init_control_stub_theory()
            .expect("idempotent control stub theory");

        for name_str in [
            "Except",
            "Except.ok",
            "Except.error",
            "Except.bind",
            "ExceptT",
            "ExceptT.mk",
            "ExceptT.run",
            "MonadExcept.throw",
            "MonadExcept.tryCatch",
            "tryCatchThe",
            "tryFinally",
        ] {
            let name = Name::from_string(name_str);
            let ci = env
                .get_const(&name)
                .unwrap_or_else(|| panic!("{name_str} not registered after init_except_t"));
            assert_eq!(ci.name, name, "{name_str}: name mismatch");
        }
    }

    #[test]
    fn test_init_except_t_idempotent() {
        let mut env = Environment::new();
        env.init_except_t().expect("first");
        env.init_except_t().expect("idempotent");
    }

    #[test]
    fn test_init_option_t() {
        let mut env = Environment::new();
        // OptionT.mk references Option, which must be initialized first
        env.init_option().expect("init_option");
        env.init_option_t().expect("init_option_t");
        assert!(env.has_option_t());

        for name_str in ["OptionT", "OptionT.mk", "OptionT.run", "OptionT.fail"] {
            let name = Name::from_string(name_str);
            let ci = env
                .get_const(&name)
                .unwrap_or_else(|| panic!("{name_str} not registered after init_option_t"));
            assert_eq!(ci.name, name, "{name_str}: name mismatch");
        }
    }

    #[test]
    fn test_init_option_t_idempotent() {
        let mut env = Environment::new();
        env.init_option().expect("init_option");
        env.init_option_t().expect("first");
        env.init_option_t().expect("idempotent");
    }

    #[test]
    fn test_except_t_key_types_well_formed() {
        use crate::expr::ExprKind;
        use crate::level::Level;
        use crate::tc::TypeChecker;

        let mut env = Environment::new();
        env.init_except_t().expect("init_except_t");
        let tc = TypeChecker::new(&env);

        // Except : Type u → Type u → Type u  (1 level param)
        for name in &["Except", "ExceptT", "MonadExcept.throw"] {
            let n = Name::from_string(name);
            let ci = env.get_const(&n).expect(name);
            let levels: Vec<Level> = ci.level_params.iter().map(|_| Level::zero()).collect();
            let expr = Expr::const_(n, levels);
            let ty = tc
                .infer_type(&expr)
                .unwrap_or_else(|e| panic!("{name}: tc.infer_type failed: {e}"));
            // All are Pi types (they take type arguments)
            assert!(
                matches!(&ty.kind, ExprKind::Pi(..)),
                "{name}: expected Pi type, got {ty:?}"
            );
        }
    }

    #[test]
    fn test_option_t_key_types_well_formed() {
        use crate::expr::ExprKind;
        use crate::level::Level;
        use crate::tc::TypeChecker;

        let mut env = Environment::new();
        env.init_option().expect("init_option");
        env.init_option_t().expect("init_option_t");
        let tc = TypeChecker::new(&env);

        for name in &["OptionT", "OptionT.mk", "OptionT.run", "OptionT.fail"] {
            let n = Name::from_string(name);
            let ci = env.get_const(&n).expect(name);
            let levels: Vec<Level> = ci.level_params.iter().map(|_| Level::zero()).collect();
            let expr = Expr::const_(n, levels);
            let ty = tc
                .infer_type(&expr)
                .unwrap_or_else(|e| panic!("{name}: tc.infer_type failed: {e}"));
            assert!(
                matches!(&ty.kind, ExprKind::Pi(..)),
                "{name}: expected Pi type, got {ty:?}"
            );
        }
    }
}
